UPDATE deployments
SET last_run_at = #{params.LastRunAt},
	next_scheduled_at = #{params.NextScheduledAt},
	updated_at = #{params.LastRunAt}
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND external_id = #{params.ExternalID}
AND schedule_revision = #{params.ScheduleRevision}
AND next_scheduled_at = #{params.ScheduledAt}
AND status = 'active'
AND archived_at IS NULL
AND deleted_at IS NULL

UPDATE deployments
SET last_run_at = #{params.LastRunAt},
	status = 'paused',
	paused_reason = CAST(#{params.PausedReason,sensitive=true} AS jsonb),
	schedule_revision = schedule_revision + 1,
	next_scheduled_at = NULL,
	updated_at = #{params.LastRunAt}
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND external_id = #{params.ExternalID}
AND schedule_revision = #{params.ScheduleRevision}
AND next_scheduled_at = #{params.ScheduledAt}
AND status = 'active'
AND archived_at IS NULL
AND deleted_at IS NULL

mapper.select:
SELECT

FROM deployments

    workspace_uuid = #{params.WorkspaceUUID}
    AND deleted_at IS NULL

        AND archived_at IS NULL


        AND agent_external_id = #{params.AgentExternalID}


        AND status = #{params.Status}


        AND created_at >= #{params.CreatedAtGTE}


        AND created_at <= #{params.CreatedAtLTE}


        AND (created_at, uuid) < (#{params.Cursor.CreatedAt}, #{params.Cursor.UUID})


ORDER BY created_at DESC, uuid DESC
LIMIT #{params.FetchLimit}

